lxml.html.clean.autolink_html:
def autolink_html(html, *args, **kw):
    result_type = type(html)
    if isinstance(html, basestring):
        doc = fromstring(html)
    else:
        doc = copy.deepcopy(html)
    autolink(doc, *args, **kw)
    return _transform_result(result_type, doc)

lxml.html.diff.end_tag:
def end_tag(el):
    """ The text representation of an end tag for a tag.  Includes
    trailing whitespace when appropriate.  """
    if (el.tail and start_whitespace_re.search(el.tail)):
        extra = ' '
    else:
        extra = ''
    return '</%s>%s' % (el.tag, extra)

lxml._elementpath._build_path_iterator:
def _build_path_iterator(path, namespaces):
    """compile selector pattern"""
    if path[-1:] == '/':
        path += '*'
    cache_key = (path, )
    if namespaces:
        if None in namespaces:
            if ('' in namespaces and namespaces[None] != namespaces['']):
                raise ValueError('Ambiguous default namespace provided: %r versus %r' % (namespaces[None], namespaces['']))
            cache_key += (namespaces[None], ) + tuple(sorted((item for item in namespaces.items() if item[0] is not None)))
        else:
            cache_key += tuple(sorted(namespaces.items()))
    try:
        return _cache[cache_key]
    except KeyError:
        pass
    if len(_cache) > 100:
        _cache.clear()
    if path[:1] == '/':
        raise SyntaxError('cannot use absolute path on element')
    stream = iter(xpath_tokenizer(path, namespaces))
    try:
        _next = stream.next
    except AttributeError:
        _next = stream.__next__
    try:
        token = _next()
    except StopIteration:
        raise SyntaxError('empty path expression')
    selector = []
    while 1:
        try:
            selector.append(ops[token[0]](_next, token))
        except StopIteration:
            raise SyntaxError('invalid path')
        try:
            token = _next()
            if token[0] == '/':
                token = _next()
        except StopIteration:
            break
    _cache[cache_key] = selector
    return selector

lxml.html.diff._move_el_inside_block:
def _move_el_inside_block(el, tag):
    """ helper for _fixup_ins_del_tags; actually takes the <ins> etc tags
    and moves them inside any block-level tags.  """
    for child in el:
        if _contains_block_level_tag(child):
            break
    else:
        children_tag = etree.Element(tag)
        children_tag.text = el.text
        el.text = None
        children_tag.extend(list(el))
        el[:] = [children_tag]
        return
    for child in list(el):
        if _contains_block_level_tag(child):
            _move_el_inside_block(child, tag)
            if child.tail:
                tail_tag = etree.Element(tag)
                tail_tag.text = child.tail
                child.tail = None
                el.insert(el.index(child) + 1, tail_tag)
        else:
            child_tag = etree.Element(tag)
            el.replace(child, child_tag)
            child_tag.append(child)
    if el.text:
        text_tag = etree.Element(tag)
        text_tag.text = el.text
        el.text = None
        el.insert(0, text_tag)

lxml.html.diff.flatten_el:
def flatten_el(el, include_hrefs, skip_tag=False):
    """ Takes an lxml element el, and generates all the text chunks for
    that tag.  Each start tag is a chunk, each word is a chunk, and each
    end tag is a chunk.

    If skip_tag is true, then the outermost container tag is
    not returned (just its contents)."""
    if not skip_tag:
        if el.tag == 'img':
            yield ('img', el.get('src'), start_tag(el))
        else:
            yield start_tag(el)
    if (el.tag in empty_tags and not el.text and not len(el) and not el.tail):
        return
    start_words = split_words(el.text)
    for word in start_words:
        yield html_escape(word)
    for child in el:
        for item in flatten_el(child, include_hrefs=include_hrefs):
            yield item
    if (el.tag == 'a' and el.get('href') and include_hrefs):
        yield ('href', el.get('href'))
    if not skip_tag:
        yield end_tag(el)
        end_words = split_words(el.tail)
        for word in end_words:
            yield html_escape(word)

lxml.html.formfill._find_form:
def _find_form(el, form_id=None, form_index=None):
    if (form_id is None and form_index is None):
        forms = _forms_xpath(el)
        for form in forms:
            return form
        raise FormNotFound('No forms in page')
    if form_id is not None:
        form = el.get_element_by_id(form_id)
        if form is not None:
            return form
        forms = _form_name_xpath(el, name=form_id)
        if forms:
            return forms[0]
        else:
            raise FormNotFound('No form with the name or id of %r (forms: %s)' % (id, ', '.join(_find_form_ids(el))))
    if form_index is not None:
        forms = _forms_xpath(el)
        try:
            return forms[form_index]
        except IndexError:
            raise FormNotFound('There is no form with the index %r (%i forms found)' % (form_index, len(forms)))

lxml.html.diff.parse_html:
def parse_html(html, cleanup=True):
    """
    Parses an HTML fragment, returning an lxml element.  Note that the HTML will be
    wrapped in a <div> tag that was not in the original document.

    If cleanup is true, make sure there's no <head> or <body>, and get
    rid of any <ins> and <del> tags.
    """
    if cleanup:
        html = cleanup_html(html)
    return fragment_fromstring(html, create_parent=True)
